    implement(me, (_, { session, fail }) => (session ? { name: session.user } : fail('Unauthorized', {}))),
    implement(start, (_, { session, redirect }) => redirect(session ? ui.link(home, null) : ui.link(login, null))),
    implement(signIn, ({ name }, { setSession }) => {
